(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[466]={"source_order":466,"notes":["The reading 'a/' is uncertain. The trailing stroke may be a vertical line, a question mark or a fold artifact.","It is not certain whether the gutter ticks are on the target page or are offset from the facing page.","Text at the far right of the canvas (x > ~3200), such as 'd.', 'e.' and 'Sa', belongs to the facing recto fol. 234 (shelfmark column fragments) and is excluded.","Faint mirrored writing visible across the whole page is show-through from fol. 233 recto. It is not target-page text and is not inventoried.","The 'a/' mark on the target page corresponds to the 'a/' visible at the left edge of the fol. 234 context image. It was assigned to the target verso because of its position left of the gutter.","Apart from the folio number and the 'a/' mark, the ruled page carries no catalogue entries. The images were reviewed across the top, middle and bottom, the margins and the interlinear spaces.","The faint mirrored writing across the page is show-through from fol. 233 recto. It is not transcribed.","There are two small tick- or hook-like marks at the gutter edge near the top (native approx. x 3110–3190, y 300–500). They may be on this page or may be offset from the facing page. They are not treated as text.","There is a very faint hook or '1'-like stroke in the lower right (approx. x 2910–2950, y 4150–4220). It is probably show-through or a stray mark.","A speckled smudge near the left middle (approx. x 620–760, y 2640–2700) is not text.","Letters such as 'd.', 'e.' and 'Sa' at the far right (x > ~3200) belong to the shelfmark column of the facing fol. 234. They are excluded.","The function of the 'a/' mark, and any link to an entry on fol. 233 or fol. 234, cannot be determined.","Two points are open. First, it is not certain whether the trailing element after 'a/' is a '?' or an artifact. Second, the function of the mark is unknown; it may relate to entries on fol. 233 or fol. 234.","It is unresolved whether the gutter ticks are on the target page or are offset from the facing recto.","Several small dark dots and short strokes are scattered across the page. Examples are at native approx. (2894, 3276) and (2539, 4691). They appear to be specks or stray marks, not writing, and are not individually recorded."],"records":[{"id":"css-prod-0466-r001","local_id":"r001","source_order":466,"folio":"233b","folio_label":"fol. 233b","sequence":1,"page_id":"afb7a8a6-d593-4877-b746-6935bf628207","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"233ᵇ","annotations":["Written at an angle in the top-left corner of the verso, in darker pencil or ink than the ruled lines.","The final character is raised above the line and written after '233'."],"uncertainties":["The raised final character is read as 'b'. Its form resembles '6', but the supplied folio label is fol. 233b.","It is unresolved whether the gutter ticks are on the target page or are offset from the facing recto.","Several small dark dots and short strokes are scattered across the page. Examples are at native approx. (2894, 3276) and (2539, 4691). They appear to be specks or stray marks, not writing, and are not individually recorded.","Proposed literal_text (probable): 233[b?]. The raised final character resembles '6' in the source. 'b' is adopted on the strength of the supplied folio label, not from a secure reading. The literal text should keep this uncertainty visible."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[345,320,150,160]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[{"record_id":"r001","field_path":"literal_text","before":"233ᵇ","after":"233[b?]","reason":"The raised final character resembles '6' in the source. 'b' is adopted on the strength of the supplied folio label, not from a secure reading. The literal text should keep this uncertainty visible.","source_block_ids":["b001"],"certainty":"probable","applied":false,"application_reason":"Retained as a proposal; source certainty is not secure"}],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/afb7a8a6-d593-4877-b746-6935bf628207.json","auditPath":"audit/pages/0466.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]},{"id":"css-prod-0466-r002","local_id":"r002","source_order":466,"folio":"233b","folio_label":"fol. 233b","sequence":2,"page_id":"afb7a8a6-d593-4877-b746-6935bf628207","kind":"note","record_type":"unattached_annotation","source_model_record_type":"unattached_annotation","subtype":"marginal_mark","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Unattached annotation","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"a/","annotations":["The mark is in faint pencil near the right (gutter-side) edge of the verso, at about the third ruled line (native approx. x 2935–3010, y 795–910).","The vertical stroke is long. A small mark or dot follows it to the right, which may be a question mark.","The mark is not attached to any catalogue entry on this page."],"uncertainties":["The reading 'a/' is uncertain. The trailing element may be a stroke, a '?' or an artifact.","The same mark is visible at the left edge of the fol. 234 context image. It is placed on this verso because it lies left of the gutter. Its purpose is unknown.","Two points are open. First, it is not certain whether the trailing element after 'a/' is a '?' or an artifact. Second, the function of the mark is unknown; it may relate to entries on fol. 233 or fol. 234.","It is unresolved whether the gutter ticks are on the target page or are offset from the facing recto.","Several small dark dots and short strokes are scattered across the page. Examples are at native approx. (2894, 3276) and (2539, 4691). They appear to be specks or stray marks, not writing, and are not individually recorded."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b002"],"locations":[{"block_id":"b002","bbox":[2925,790,100,130]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/afb7a8a6-d593-4877-b746-6935bf628207.json","auditPath":"audit/pages/0466.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
